use base64::Engine as _;
use base64::engine::general_purpose::URL_SAFE;
use sha2::{Digest, Sha256};
#[path = "support/go_oracle.rs"]
mod go_oracle;

use symeraseme_core::storage::encryption::{
    EncryptionError, V1_HEADER, V2_HEADER, V2_SALT_LEN, V3_HEADER, V3_SALT_LEN, decrypt_v1,
    decrypt_v2, decrypt_v3, is_legacy_go_envelope,
};

// This envelope was generated by scripts/generate-crypto-fixtures.py through
// the archived python-final implementation. The plaintext is the shared DB
// fixture that the Go TestPythonFernetFixturesDecrypt test also compares.
const PYTHON_FINAL_V1: &[u8] =
    include_bytes!("../../../tests/fixtures/event-store/crypto/golden-campaign-v1-python.db");
const PYTHON_FINAL_V2: &[u8] =
    include_bytes!("../../../tests/fixtures/event-store/crypto/golden-campaign-v2-python.db");
const PYTHON_FINAL_V3: &[u8] =
    include_bytes!("../../../tests/fixtures/event-store/crypto/golden-campaign-v3-python.db");
const PYTHON_FINAL_SMALL_V3: &[u8] =
    include_bytes!("../../../tests/fixtures/event-store/crypto/small-vector-v3-python.db");
const SHARED_PLAINTEXT: &[u8] =
    include_bytes!("../../../tests/fixtures/event-store/golden-campaign.db");
const MASTER_KEY: &[u8] = b"symaira-eraseme-golden-master-32";
const EXPECTED_CRY006_SOURCE_SHA256: &str =
    "1892a69846a06d7ca41dfffe0b1da81947bd2aacbb32e475092eadfaab689bba";
type DecryptFn = fn(&[u8], &[u8]) -> Result<Vec<u8>, EncryptionError>;

#[test]
fn python_final_v1_fixture_matches_shared_go_plaintext() {
    let decrypted =
        decrypt_v1(PYTHON_FINAL_V1, MASTER_KEY).expect("the Python-final V1 vector must decrypt");

    assert!(
        decrypted == SHARED_PLAINTEXT,
        "CRY-001 plaintext differs from the shared Go/Python fixture"
    );
}

#[test]
fn v1_rejects_tampering_before_decryption() {
    let mut tampered = PYTHON_FINAL_V1.to_vec();
    let token_start = V1_HEADER.len();
    tampered[token_start + 1] = if tampered[token_start + 1] == b'B' {
        b'C'
    } else {
        b'B'
    };

    assert!(matches!(
        decrypt_v1(&tampered, MASTER_KEY),
        Err(EncryptionError::AuthenticationFailed)
    ));
}

#[test]
fn v1_rejects_truncated_wrong_key_and_unsupported_inputs() {
    assert!(matches!(
        decrypt_v1(&PYTHON_FINAL_V1[..V1_HEADER.len()], MASTER_KEY),
        Err(EncryptionError::TruncatedToken)
    ));

    let mut truncated = PYTHON_FINAL_V1.to_vec();
    truncated.pop();
    assert!(decrypt_v1(&truncated, MASTER_KEY).is_err());

    let wrong_master_key = [0_u8; 32];
    assert!(matches!(
        decrypt_v1(PYTHON_FINAL_V1, &wrong_master_key),
        Err(EncryptionError::AuthenticationFailed)
    ));

    let mut unsupported = PYTHON_FINAL_V1.to_vec();
    unsupported[..V1_HEADER.len()].copy_from_slice(b"SYMERASEME_ENCv2\n");
    assert!(matches!(
        decrypt_v1(&unsupported, MASTER_KEY),
        Err(EncryptionError::UnsupportedEnvelope)
    ));

    let short_master_key = [0_u8; 31];
    assert!(matches!(
        decrypt_v1(PYTHON_FINAL_V1, &short_master_key),
        Err(EncryptionError::InvalidMasterKeyLength { actual: 31 })
    ));
}

#[test]
fn python_final_v2_fixture_matches_shared_go_plaintext() {
    assert_eq!(V2_HEADER.len(), 17);
    assert!(PYTHON_FINAL_V2.len() >= V2_HEADER.len() + V2_SALT_LEN);
    assert_eq!(&PYTHON_FINAL_V2[..V2_HEADER.len()], V2_HEADER);

    let decrypted =
        decrypt_v2(PYTHON_FINAL_V2, MASTER_KEY).expect("the Python-final V2 vector must decrypt");

    assert!(
        decrypted == SHARED_PLAINTEXT,
        "CRY-002 plaintext differs from the shared Go/Python fixture"
    );
}

#[test]
fn v2_rejects_malformed_header_and_salt_truncation() {
    let mut malformed_header = PYTHON_FINAL_V2.to_vec();
    malformed_header[..V2_HEADER.len()].copy_from_slice(V1_HEADER);
    assert!(matches!(
        decrypt_v2(&malformed_header, MASTER_KEY),
        Err(EncryptionError::UnsupportedEnvelope)
    ));

    assert!(matches!(
        decrypt_v2(&PYTHON_FINAL_V2[..V2_HEADER.len()], MASTER_KEY),
        Err(EncryptionError::TruncatedEnvelope { version: 2 })
    ));

    let truncated_salt = &PYTHON_FINAL_V2[..V2_HEADER.len() + V2_SALT_LEN - 1];
    assert!(matches!(
        decrypt_v2(truncated_salt, MASTER_KEY),
        Err(EncryptionError::TruncatedEnvelope { version: 2 })
    ));

    let token_start = V2_HEADER.len() + V2_SALT_LEN;
    assert!(matches!(
        decrypt_v2(&PYTHON_FINAL_V2[..token_start], MASTER_KEY),
        Err(EncryptionError::TruncatedToken)
    ));
}

#[test]
fn v2_rejects_wrong_master_key_and_tampered_token() {
    let wrong_master_key = [0_u8; 32];
    assert!(matches!(
        decrypt_v2(PYTHON_FINAL_V2, &wrong_master_key),
        Err(EncryptionError::AuthenticationFailed)
    ));

    let mut tampered = PYTHON_FINAL_V2.to_vec();
    let token_start = V2_HEADER.len() + V2_SALT_LEN;
    let tamper_at = token_start + 10;
    tampered[tamper_at] = if tampered[tamper_at] == b'A' {
        b'B'
    } else {
        b'A'
    };
    assert!(matches!(
        decrypt_v2(&tampered, MASTER_KEY),
        Err(EncryptionError::AuthenticationFailed)
    ));
}

#[test]
fn v2_rejects_invalid_and_unsupported_fernet_tokens() {
    let token_start = V2_HEADER.len() + V2_SALT_LEN;
    let mut invalid_base64 = PYTHON_FINAL_V2[..token_start].to_vec();
    invalid_base64.push(b'%');
    assert!(matches!(
        decrypt_v2(&invalid_base64, MASTER_KEY),
        Err(EncryptionError::InvalidBase64)
    ));

    let mut frame = URL_SAFE
        .decode(&PYTHON_FINAL_V2[token_start..])
        .expect("the committed V2 token must be decodable");
    frame[0] = 0x81;
    let unsupported_token = URL_SAFE.encode(frame);
    let mut unsupported_version = PYTHON_FINAL_V2[..token_start].to_vec();
    unsupported_version.extend_from_slice(unsupported_token.as_bytes());
    assert!(matches!(
        decrypt_v2(&unsupported_version, MASTER_KEY),
        Err(EncryptionError::UnsupportedFernetVersion(0x81))
    ));

    let short_master_key = [0_u8; 31];
    assert!(matches!(
        decrypt_v2(PYTHON_FINAL_V2, &short_master_key),
        Err(EncryptionError::InvalidMasterKeyLength { actual: 31 })
    ));
}

#[test]
fn python_final_v3_fixture_matches_shared_go_plaintext() {
    assert_eq!(V3_HEADER.len(), 17);
    assert!(PYTHON_FINAL_V3.len() >= V3_HEADER.len() + V3_SALT_LEN);
    assert_eq!(&PYTHON_FINAL_V3[..V3_HEADER.len()], V3_HEADER);

    let decrypted =
        decrypt_v3(PYTHON_FINAL_V3, MASTER_KEY).expect("the Python-final V3 vector must decrypt");
    assert_eq!(decrypted, SHARED_PLAINTEXT);

    let small = decrypt_v3(PYTHON_FINAL_SMALL_V3, MASTER_KEY)
        .expect("the small Python-final V3 vector must decrypt");
    assert_eq!(
        small,
        b"SQLite format 3\0deterministic test payload for small vector verification."
    );
}

#[test]
fn v3_rejects_malformed_header_salt_token_and_key() {
    let mut malformed_header = PYTHON_FINAL_V3.to_vec();
    malformed_header[..V3_HEADER.len()].copy_from_slice(V2_HEADER);
    assert!(matches!(
        decrypt_v3(&malformed_header, MASTER_KEY),
        Err(EncryptionError::UnsupportedEnvelope)
    ));

    assert!(matches!(
        decrypt_v3(&PYTHON_FINAL_V3[..V3_HEADER.len()], MASTER_KEY),
        Err(EncryptionError::TruncatedEnvelope { version: 3 })
    ));
    let token_start = V3_HEADER.len() + V3_SALT_LEN;
    assert!(matches!(
        decrypt_v3(&PYTHON_FINAL_V3[..token_start - 1], MASTER_KEY),
        Err(EncryptionError::TruncatedEnvelope { version: 3 })
    ));
    assert!(matches!(
        decrypt_v3(&PYTHON_FINAL_V3[..token_start], MASTER_KEY),
        Err(EncryptionError::TruncatedToken)
    ));

    let wrong_master_key = [0_u8; 32];
    assert!(matches!(
        decrypt_v3(PYTHON_FINAL_V3, &wrong_master_key),
        Err(EncryptionError::AuthenticationFailed)
    ));

    let short_master_key = [0_u8; 31];
    assert!(matches!(
        decrypt_v3(PYTHON_FINAL_V3, &short_master_key),
        Err(EncryptionError::InvalidMasterKeyLength { actual: 31 })
    ));
}

#[test]
fn v3_rejects_tampered_invalid_base64_and_unsupported_fernet_tokens() {
    let token_start = V3_HEADER.len() + V3_SALT_LEN;
    let mut tampered = PYTHON_FINAL_V3.to_vec();
    tampered[token_start + 10] = if tampered[token_start + 10] == b'A' {
        b'B'
    } else {
        b'A'
    };
    assert!(matches!(
        decrypt_v3(&tampered, MASTER_KEY),
        Err(EncryptionError::AuthenticationFailed)
    ));

    let mut invalid_base64 = PYTHON_FINAL_V3[..token_start].to_vec();
    invalid_base64.push(b'%');
    assert!(matches!(
        decrypt_v3(&invalid_base64, MASTER_KEY),
        Err(EncryptionError::InvalidBase64)
    ));

    let mut frame = URL_SAFE
        .decode(&PYTHON_FINAL_V3[token_start..])
        .expect("the committed V3 token must be decodable");
    frame[0] = 0x81;
    let unsupported_token = URL_SAFE.encode(frame);
    let mut unsupported_version = PYTHON_FINAL_V3[..token_start].to_vec();
    unsupported_version.extend_from_slice(unsupported_token.as_bytes());
    assert!(matches!(
        decrypt_v3(&unsupported_version, MASTER_KEY),
        Err(EncryptionError::UnsupportedFernetVersion(0x81))
    ));
}

#[test]
fn python_final_v3_fixture_matches_oracle_provenance() {
    let provenance: serde_json::Value = serde_json::from_slice(include_bytes!(
        "../../../tests/fixtures/event-store/crypto/provenance.json"
    ))
    .expect("the committed crypto provenance must be valid JSON");
    let expected = provenance["fixtures"]["golden-campaign-v3-python.db"]["sha256"]
        .as_str()
        .expect("the V3 oracle fixture must have a SHA-256 provenance record");
    let actual = Sha256::digest(PYTHON_FINAL_V3);
    assert_eq!(hex::encode(actual), expected);
}

#[test]
fn rust_writer_is_consumed_by_go_oracle_and_go_writer_by_rust() {
    let key = [0x41_u8; 32];
    let plaintext = b"SQLite format 3\0binary\xff payload at a block boundary";
    let run = |operation: u8, payload: &[u8]| {
        let mut request = Vec::with_capacity(33 + payload.len());
        request.push(operation);
        request.extend_from_slice(&key);
        request.extend_from_slice(payload);
        let run = go_oracle::run_oracle("crypto", Some(&request));
        assert!(run.status.success(), "Go oracle failed: {:?}", run.stderr);
        run.stdout
    };

    let rust_envelope = symeraseme_core::storage::encryption::encrypt_v3(plaintext, &key)
        .expect("Rust V3 writer must succeed");
    assert_eq!(run(b'd', &rust_envelope), plaintext);

    let go_envelope = run(b'e', plaintext);
    assert_eq!(decrypt_v3(&go_envelope, &key).unwrap(), plaintext);
}

#[test]
fn pinned_go_legacy_fixtures_decrypt_for_all_envelope_versions() {
    let cases: [(&[u8], DecryptFn); 2] = [
        (
            include_bytes!(
                "../../../tests/fixtures/event-store/crypto/golden-campaign-v1-legacy-go.db"
            )
            .as_slice(),
            decrypt_v1,
        ),
        (
            include_bytes!(
                "../../../tests/fixtures/event-store/crypto/golden-campaign-v2-legacy-go.db"
            )
            .as_slice(),
            decrypt_v2,
        ),
    ];
    for (fixture, decrypt) in cases {
        assert!(is_legacy_go_envelope(fixture));
        assert_eq!(decrypt(fixture, MASTER_KEY).unwrap(), SHARED_PLAINTEXT);
    }

    for fixture in [
        include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v3-legacy-go.db"
        )
        .as_slice(),
        include_bytes!("../../../tests/fixtures/event-store/crypto/small-vector-v3-legacy-go.db")
            .as_slice(),
    ] {
        assert!(is_legacy_go_envelope(fixture));
        let plaintext = decrypt_v3(fixture, MASTER_KEY).unwrap();
        if fixture.len() == 175 {
            assert_eq!(
                plaintext,
                b"SQLite format 3\0deterministic test payload for small vector verification."
            );
        } else {
            assert_eq!(plaintext, SHARED_PLAINTEXT);
        }
    }
}

#[test]
fn legacy_go_detection_does_not_classify_standard_or_malformed_frames() {
    assert!(!is_legacy_go_envelope(PYTHON_FINAL_V3));
    assert!(!is_legacy_go_envelope(
        &PYTHON_FINAL_V3[..V3_HEADER.len() + V3_SALT_LEN]
    ));
    let mut malformed = PYTHON_FINAL_V3.to_vec();
    let token_start = V3_HEADER.len() + V3_SALT_LEN;
    malformed[token_start] = 0x80;
    assert!(!is_legacy_go_envelope(&malformed[..token_start + 68]));
}

#[test]
fn legacy_go_rejects_wrong_key_and_tampering_without_plaintext() {
    let fixture =
        include_bytes!("../../../tests/fixtures/event-store/crypto/small-vector-v3-legacy-go.db");
    let wrong_key = [0_u8; 32];
    assert!(matches!(
        decrypt_v3(fixture, &wrong_key),
        Err(EncryptionError::LegacyTokenInvalid)
    ));

    let mut tampered = fixture.to_vec();
    let token_start = V3_HEADER.len() + V3_SALT_LEN;
    tampered[token_start + 9 + 12] ^= 0x01;
    assert!(matches!(
        decrypt_v3(&tampered, MASTER_KEY),
        Err(EncryptionError::LegacyTokenInvalid)
    ));

    let mut hmac_tampered = fixture.to_vec();
    let last = hmac_tampered.len() - 1;
    hmac_tampered[last] ^= 0x01;
    assert!(matches!(
        decrypt_v3(&hmac_tampered, MASTER_KEY),
        Err(EncryptionError::LegacyTokenInvalid)
    ));
}

#[derive(Debug)]
struct Cry006Case {
    id: String,
    version: u8,
    fixture: String,
    outcome: String,
    error: Option<String>,
    plaintext_sha256: Option<String>,
}

fn cry006_fixture(name: &str) -> &[u8] {
    match name {
        "golden-campaign-v1-legacy-go.db" => include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v1-legacy-go.db"
        ),
        "golden-campaign-v2-legacy-go.db" => include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v2-legacy-go.db"
        ),
        "golden-campaign-v3-legacy-go.db" => include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v3-legacy-go.db"
        ),
        "golden-campaign-v1-python.db" => include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v1-python.db"
        ),
        "golden-campaign-v2-python.db" => include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v2-python.db"
        ),
        "golden-campaign-v3-python.db" => include_bytes!(
            "../../../tests/fixtures/event-store/crypto/golden-campaign-v3-python.db"
        ),
        other => panic!("unexpected CRY006 fixture {other}"),
    }
}

fn cry006_decrypt(version: u8) -> DecryptFn {
    match version {
        1 => decrypt_v1,
        2 => decrypt_v2,
        3 => decrypt_v3,
        other => panic!("unexpected CRY006 version {other}"),
    }
}

fn cry006_mutate(raw: &[u8], kind: &str, version: u8, fixture: &str) -> Vec<u8> {
    let (header, salt) = match version {
        1 => (V1_HEADER.len(), 0),
        2 => (V2_HEADER.len(), V2_SALT_LEN),
        3 => (V3_HEADER.len(), V3_SALT_LEN),
        other => panic!("unexpected CRY006 version {other}"),
    };
    let mut out = raw.to_vec();
    match kind {
        "valid" | "wrong_key" => {}
        "malformed_header" => out[..header].copy_from_slice(b"SYMERASEME_ENCv9\n"),
        "short" => out.truncate(header),
        "short_token" => out.truncate(header + salt),
        "hmac_tamper" | "gcm_failure" => {
            let offset = if salt == 0 { header } else { header + salt };
            let mutation_offset = offset + out[offset..].len() / 2;
            out[mutation_offset] ^= 1;
        }
        "raw_standard_valid" => {
            let offset = header + salt;
            let frame = URL_SAFE
                .decode(&out[offset..])
                .expect("standard fixture token must decode");
            out.truncate(offset);
            out.extend_from_slice(&frame);
        }
        "raw_standard_tamper" => {
            assert!(fixture.ends_with("-python.db"));
            let offset = header + salt;
            let mut frame = URL_SAFE
                .decode(&out[offset..])
                .expect("standard fixture token must decode");
            frame[30] ^= 1;
            out.truncate(offset);
            out.extend_from_slice(&frame);
        }
        other => panic!("unexpected CRY006 mutation {other}"),
    }
    out
}

fn cry006_source_digest(document: &serde_json::Value) -> Result<&str, &'static str> {
    let digest = document["oracle_source_sha256"]
        .as_str()
        .ok_or("missing oracle source digest")?;
    if digest != EXPECTED_CRY006_SOURCE_SHA256 {
        return Err("oracle source digest is not the pinned authoritative source");
    }
    Ok(digest)
}

#[test]
fn cry006_table_consumes_every_pinned_go_oracle_case() {
    let document: serde_json::Value = serde_json::from_slice(include_bytes!(
        "../../../tests/fixtures/event-store/crypto/cry006-go-oracle.json"
    ))
    .expect("CRY006 oracle fixture must be valid JSON");
    assert_eq!(
        document["oracle_commit"],
        "bf53346eec234929bedf0314b99e3da85dbb991b"
    );
    assert_eq!(
        cry006_source_digest(&document).unwrap(),
        EXPECTED_CRY006_SOURCE_SHA256
    );
    assert_eq!(
        document["generator"],
        "rust-tests/parity/oracle/cry006/main.go"
    );
    assert_eq!(
        hex::encode(Sha256::digest(include_bytes!(
            "../../../rust-tests/parity/oracle/cry006/main.go"
        ))),
        document["generator_sha256"].as_str().unwrap()
    );
    for (name, expected) in document["fixture_sha256"].as_object().unwrap() {
        assert_eq!(
            hex::encode(Sha256::digest(cry006_fixture(name))),
            expected.as_str().unwrap(),
            "fixture {name}"
        );
    }
    let cases: Vec<Cry006Case> = document["cases"]
        .as_array()
        .unwrap()
        .iter()
        .map(|case| Cry006Case {
            id: case["id"].as_str().unwrap().to_owned(),
            version: case["version"].as_u64().unwrap() as u8,
            fixture: case["fixture"].as_str().unwrap().to_owned(),
            outcome: case["outcome"].as_str().unwrap().to_owned(),
            error: case["error"].as_str().map(str::to_owned),
            plaintext_sha256: case["plaintext_sha256"].as_str().map(str::to_owned),
        })
        .collect();
    assert_eq!(cases.len(), 27);
    let expected_ids: Vec<String> = (1..=3)
        .flat_map(|version| {
            [
                "valid",
                "malformed_header",
                "short",
                "short_token",
                "wrong_key",
                "hmac_tamper",
                "gcm_failure",
                "raw_standard_valid",
                "raw_standard_tamper",
            ]
            .into_iter()
            .map(move |kind| format!("v{version}_{kind}"))
        })
        .collect();
    assert_eq!(
        cases.iter().map(|case| case.id.clone()).collect::<Vec<_>>(),
        expected_ids
    );
    let mut observed_ids = Vec::with_capacity(cases.len());
    for case in &cases {
        let kind = case.id.split_once('_').unwrap().1;
        let input = cry006_mutate(
            cry006_fixture(&case.fixture),
            kind,
            case.version,
            &case.fixture,
        );
        let result = if kind == "wrong_key" {
            cry006_decrypt(case.version)(&input, &[0_u8; 32])
        } else {
            cry006_decrypt(case.version)(&input, MASTER_KEY)
        };
        observed_ids.push(case.id.clone());
        match (case.outcome.as_str(), result) {
            ("success", Ok(plaintext)) => assert_eq!(
                hex::encode(Sha256::digest(plaintext)),
                case.plaintext_sha256.as_deref().unwrap(),
                "{}",
                case.id
            ),
            ("error", Err(error)) => assert_eq!(
                error.to_string(),
                case.error.as_deref().unwrap(),
                "{}",
                case.id
            ),
            (expected, actual) => panic!("{} expected {expected}, got {actual:?}", case.id),
        }
    }
    assert_eq!(observed_ids, expected_ids);
}

#[test]
fn cry006_source_provenance_rejects_mutated_digest() {
    let mut document: serde_json::Value = serde_json::from_slice(include_bytes!(
        "../../../tests/fixtures/event-store/crypto/cry006-go-oracle.json"
    ))
    .unwrap();
    assert_eq!(
        cry006_source_digest(&document),
        Ok(EXPECTED_CRY006_SOURCE_SHA256)
    );
    document["oracle_source_sha256"] = serde_json::Value::String("00".repeat(32));
    assert_eq!(
        cry006_source_digest(&document),
        Err("oracle source digest is not the pinned authoritative source")
    );
}
